-- i18n_italian_seed_v3.sql
-- Copia IDENTICA di i18n_italian_seed_v2.sql dopo la correzione della riga 62
-- ('Eta'' -> 'Età'). Serve perche' in prod la v2 risulta gia' registrata in
-- schema_migrations (col checksum del file rotto): il client mysql si era
-- fermato alla riga 62 e le traduzioni successive non sono mai entrate. Un nome
-- nuovo = il tracker la applica come file nuovo; e' idempotente (ON DUPLICATE KEY
-- UPDATE), quindi innocua dove le righe esistono gia'.

-- =============================================================
-- Asteria Core — Localizzazione italiana per emulator_texts (v2)
-- =============================================================
--
-- Estende il seed v1 con 512 chiavi aggiuntive tradotte (comandi staff,
-- messaggi scripter/security, NUX, essentials, rosie, etc.). Idempotente
-- via INSERT ... ON DUPLICATE KEY UPDATE: se la chiave esiste gia' (con
-- un'altra lingua) viene aggiornata; se manca, viene creata.
--
-- Strategia: tradotte tutte le 512 chiavi mancanti per coprire i comandi
-- piu' usati dallo staff/utente, i messaggi inline dei comandi essentials,
-- i tutorial NUX, le warning scripter (security audit) e i messaggi
-- transazionali rosie (compravendita stanze).
--
-- Schema (gia' presente in BaseDB):
--   CREATE TABLE emulator_texts (
--     `key` varchar(100) NOT NULL PRIMARY KEY,
--     `value` varchar(4096) NOT NULL DEFAULT ''
--   );
--
-- Per applicarla:
--   mysql -u root ms < EMU/sqlupdates/i18n_italian_seed_v2.sql
--   poi nel server: ":reloadtexts" (comando staff)

START TRANSACTION;


COMMIT;
